const recountItem = `-- name: RecountItem :one
SELECT
  count(*) FILTER (WHERE value = 1 AND counted)::int AS likes,
  count(*) FILTER (WHERE value = -1 AND counted)::int AS dislikes
FROM votes WHERE item_id = $1
`

type RecountItemRow struct {
	Likes    int32
	Dislikes int32
}

func (q *Queries) RecountItem(ctx context.Context, itemID int64) (RecountItemRow, error) {
	row := q.db.QueryRow(ctx, recountItem, itemID)
	var i RecountItemRow
	err := row.Scan(&i.Likes, &i.Dislikes)
	return i, err
}

